"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 dev checkpoint (plan 8.1 step 3, 7.5): every local system on dev at its dev operating point.

Score systems (L1, L2, L3, T, T0, T0-single, B2-local): thresholds (th_s, th_r) by p1v4_score.operating_point (floors
>= 90% each, then the five-part mean). Rule systems (B1-strong) and references (plan 6.5) give decisions directly.
API rivals (B2-fast, B2-strong, B3) and the reference B2-ideal (added 2026-11-16): each at the setting its dev choice
picked (scripts/p1v4_api.py choose), thresholds by the same rule.
Ours = the best of L1, L2, L3 by the same rule. Reported (dev only; dev numbers are optimistic for every system that
chose settings on dev, the rules most of all):
  - per system: five-part mean, the parts, floors, the audio-decisive part, episode point types;
  - ours minus each local rival (B1-strong, B2-local) and minus T, T0, T0-single: five-part mean, each part and the
    audio-decisive part, with three-factor intervals (plan 7.1);
  - basic checks (plan 7.5): ours >= VoxTurn alone + 30 points; T0 on the audio-decisive part about 0 (> 10% means the
    text leaks the answer);
  - the two pre-specified diagnostics (S-react ring split, episode R pause split).
usage: python -X utf8 scripts/p1v4_dev_report.py [out.json]
"""
import json
import os
import sys
from collections import defaultdict

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
SCORE_SYSTEMS = {"L1": f"{R}/l1/scores_dev.json", "L2": f"{R}/l2/scores_dev.json", "L3": f"{R}/l3/scores_dev.json",
                 "T": f"{R}/t/scores_dev.json", "T0": f"{R}/t0/scores_dev.json",
                 "T0-single": f"{R}/t0single/scores_dev.json"}
RULE_SYSTEMS = {"B1-strong": f"{R}/b1/decisions_dev.json", "VoxTurn alone": f"{R}/refs/voxturn_decisions_dev.json",
                "No environment": f"{R}/refs/noenv_decisions_dev.json", "Copy previous": f"{R}/refs/copy_decisions_dev.json"}
API_SYSTEMS = {"B2-fast": "b2fast", "B2-strong": "b2strong", "B3": "b3", "B2-ideal": "b2ideal"}  # scripts/p1v4_api.py
OURS = ("L1", "L2", "L3")
RIVALS = ("B1-strong", "B2-local", "B2-fast", "B2-strong", "B3")
ATTRIBUTION = ("T", "T0", "T0-single")
REFERENCES = ("B2-ideal",)                  # plan 6.5: reported only, in no selection or decision


def keyed(d):
    return {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}


def point_ok(p, d):
    g = p["gold"]
    return (g.get("S") is None or d.get("S") == g["S"]) and (g.get("R") is None or d.get("R") == g["R"])


def episode_types(rows, dec):
    acc = defaultdict(list)
    ex = S.excluded_units()
    for r in rows:
        if r["part"] != "episode" or r["subset"] is not None or r["unit"] in ex:
            continue
        for p in r["points"]:
            acc[p.get("category")].append(point_ok(p, dec.get((r["unit"], r["version"], p["k"]), {})))
    out = {k: (float(np.mean(v)), len(v)) for k, v in sorted(acc.items())}
    out["mean_of_types"] = float(np.mean([v[0] for v in out.values()]))
    return out


def version_table(rows, dec):
    """Point accuracy (S and R as scored) per single-line part and version, and per floor kind (for the error
    analysis; the parts themselves are scored by group accuracy)."""
    acc = defaultdict(list)
    ex = S.excluded_units()
    for r in rows:
        if r["unit"] in ex or r["subset"] is not None or r["part"] == "episode":
            continue
        name = f"floor {r['spec']['which'].split('_')[0]}" if r["part"] == "floor" else f"{r['part']} v{r['version']}"
        for p in r["points"]:
            if p["gold"].get("S") is None and p["gold"].get("R") is None:
                continue
            acc[name].append(point_ok(p, dec.get((r["unit"], r["version"], p["k"]), {})))
    return {k: (float(np.mean(v)), len(v)) for k, v in sorted(acc.items())}


def main(out_path="results/main_v04/dev_report.json"):
    rows = D.load_rows("dev")
    groups = S.load_groups("dev")
    systems, op = {}, {}
    for name, path in SCORE_SYSTEMS.items():
        if os.path.exists(path):
            sc = keyed(json.load(open(path)))
            op[name] = S.operating_point(rows, sc)
            systems[name] = S.decide(sc, op[name]["th_s"], op[name]["th_r"])
    b2 = f"{R}/b2local/b2local_dev.json"
    b2_settings = None
    if os.path.exists(b2):
        info = json.load(open(b2))
        K, rd = info["chosen_K"], info["chosen_reading"]
        sc = keyed(json.load(open(f"{R}/b2local/scores_dev_K{K}_{rd}.json")))
        op["B2-local"] = S.operating_point(rows, sc)
        op["B2-local"].update(K=K, reading=rd)
        systems["B2-local"] = S.decide(sc, op["B2-local"]["th_s"], op["B2-local"]["th_r"])
        b2_settings = [{k: e.get(k) for k in ("K", "reading", "dropped", "primary", "floors_met", "lowest_floor",
                                              "th_s", "th_r")} for e in info["log"]]
    api_settings = {}
    for name, sd in API_SYSTEMS.items():                 # each at the setting its dev choice picked (p1v4_api choose)
        path = f"{R}/api/{sd}/{sd}_dev.json"
        if not os.path.exists(path) or not json.load(open(path)).get("chosen"):
            continue
        info = json.load(open(path))
        sc = keyed(json.load(open(f"{R}/api/{sd}/scores_dev_{info['chosen']}.json")))
        op[name] = S.operating_point(rows, sc)
        op[name].update(setting=info["chosen"])
        systems[name] = S.decide(sc, op[name]["th_s"], op[name]["th_r"])
        api_settings[name] = [{k: e.get(k) for k in ("setting", "primary", "floors_met", "lowest_floor", "th_s",
                                                     "th_r", "missing", "usd")} for e in info["log"]]
    for name, path in RULE_SYSTEMS.items():
        if os.path.exists(path):
            systems[name] = keyed(json.load(open(path)))
    tables = {n: S.unit_table(rows, d, groups) for n, d in systems.items()}
    report = {"systems": {}, "b2local_settings": b2_settings, "api_settings": api_settings}
    for n, T in tables.items():
        m = S.metrics(T)
        report["systems"][n] = {"primary": m["primary"], "parts": m["parts"], "floors": m["floors"],
                                "floor_mean": m["floor_mean"], "audio": m["audio"], "unseen": m["unseen"],
                                "operating_point": op.get(n),
                                "episode_types": episode_types(rows, systems[n]),
                                "versions": version_table(rows, systems[n]),
                                "s_react_ring_split": S.s_react_ring_split(rows, systems[n]),
                                "episode_r_split": S.episode_r_split(rows, systems[n])}
    ours = [n for n in OURS if n in tables]
    if ours:
        best = max(ours, key=lambda n: (op[n]["floors_met"], op[n]["primary"], op[n]["lowest_floor"]))
        report["ours"] = best
        comp = {}
        for other in [x for x in RIVALS + ATTRIBUTION + REFERENCES + ("VoxTurn alone", "No environment")
                      if x in tables]:
            comp[other] = {w: S.interval(tables[best], tables[other], w)
                           for w in ["primary", "audio"] + [f"part:{p}" for p in S.PARTS]}
        report["comparisons"] = comp
        if "VoxTurn alone" in tables:
            gap = report["systems"][best]["primary"] - report["systems"]["VoxTurn alone"]["primary"]
            report["check_voxturn_gap"] = {"gap": gap, "pass": gap >= 0.30}
        if "T0" in tables:
            a = report["systems"]["T0"]["audio"]
            report["check_t0_audio"] = {"t0_audio": a, "pass": a <= 0.10}
        # dev preview of the decision table (plan 7.2-7.4; the decision itself is made on test). The unseen subsets
        # exist only in test and replication, so that condition cannot be previewed on dev.
        prev = {}
        for other in [x for x in RIVALS if x in tables]:
            c = comp[other]["primary"]
            fd = report["systems"][best]["floor_mean"] - report["systems"][other]["floor_mean"]
            prev[other] = {"primary_diff": c["point"], "ci95": c["ci95"],
                           "wins": bool(c["point"] >= 0.05 and c["ci95"][0] > 0), "floor_mean_diff": fd,
                           "floors_ok": bool(fd >= -0.05)}
        listen = {}
        for other in [x for x in ("T",) + RIVALS if x in tables]:
            c = comp[other]["audio"]
            listen[other] = {"audio_diff": c["point"], "ci95": c["ci95"],
                             "pass": bool(c["point"] >= 0.05 and c["ci95"][0] > 0)}
        report["decision_preview"] = {"main": prev, "listen": listen,
                                      "note": "dev only; rivals not yet run are missing; unseen subsets: test only"}
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    json.dump(report, open(out_path, "w"), indent=1)
    print(f"{'system':16s} {'primary':>8s} " + " ".join(f"{p:>8s}" for p in S.PARTS) + "    audio  low floor")
    for n, s in report["systems"].items():
        low = min(s["floors"].values()) if s["floors"] else float("nan")
        print(f"{n:16s} {s['primary']:8.3f} " + " ".join(f"{s['parts'].get(p, float('nan')):8.3f}" for p in S.PARTS)
              + f" {s['audio']:8.3f} {low:8.3f}")
    if b2_settings:
        print("B2-local settings on dev:", json.dumps(b2_settings))
    for name, st in api_settings.items():
        print(f"{name} settings on dev (chosen {op[name]['setting']}):", json.dumps(st))
    if ours:
        print("ours =", report["ours"])
        for other, c in report["comparisons"].items():
            x = c["primary"]
            print(f"  ours - {other:14s} {x['point']:+.3f} [{x['ci95'][0]:+.3f}, {x['ci95'][1]:+.3f}]  "
                  + " ".join(f"{p[5:]}:{c[p]['point']:+.2f}" for p in c if p.startswith("part:"))
                  + f"  audio:{c['audio']['point']:+.3f} [{c['audio']['ci95'][0]:+.3f}, {c['audio']['ci95'][1]:+.3f}]")
        print("checks:", json.dumps({k: report[k] for k in ("check_voxturn_gap", "check_t0_audio") if k in report}))
        print("decision preview (dev):", json.dumps(report["decision_preview"]))


if __name__ == "__main__":
    main(*sys.argv[1:2])
